static void
uw_receiver_test(void)
{
	const struct sensor *c = &sensors[2];
	vm_offset_t csis = ml_io_map(ISPFE_CSIS_PHYS, 0xd0000), sysreg = ml_io_map(ISPFE_SYSREG_PHYS, 0x1000);
	vm_offset_t pmu = ml_io_map(0x15462000ULL, 0x2000), fe = 0;
	uint8_t one = 1, zero = 0, fc = 0;
	unsigned on = 0, uwfe = 0;

	if (!(rd(pmu + 0x484) & 1u)) {
		printf("akita camera: uw: pd-ispfe is off: not trying\n");
		return;
	}
	{
		/* S2MPG15 LDO2S "L2S_PLL_MIPI_UFS" (the MIPI PHYs' PLL supply; Android 850 mV: 300 mV + 12.5 mV x code -> 0x2c)
		 * and L12S (CAMIO, 700 mV + 25 mV x code; Android 1.8 V -> 0x2c) as found; camera_l2s=CODE sets L2S's code */
		uint8_t l2 = 0, l12 = 0;
		unsigned set = 0;

		spmic(false, S2MPG15_PM, 0x30, &l2);
		spmic(false, S2MPG15_PM, S2MPG15_L12S_CTRL, &l12);
		{
			/* VDD_CAM = S2MPG15 BUCK1S (CTRL 0x0e, OUT1 0x0f, OUT2 0xca; 200 mV + 6.25 mV x code; Android 518.75 mV = 0x33) and
			 * BUCK11S "VDD_INT_M" (OUT1 0x24) */
			uint8_t c1 = 0, o1 = 0, o2 = 0, b11 = 0;

			spmic(false, S2MPG15_PM, 0x0e, &c1);
			spmic(false, S2MPG15_PM, 0x0f, &o1);
			spmic(false, S2MPG15_PM, 0xca, &o2);
			spmic(false, S2MPG15_PM, 0x24, &b11);
			printf("akita camera: uw: VDD_CAM B1S_CTRL %#x OUT1 %#x (%u uV) OUT2 %#x (%u uV); B11S_OUT1 %#x (%u uV)\n", c1, o1,
			    200000 + o1 * 6250, o2, 200000 + o2 * 6250, b11, 200000 + b11 * 6250);
		}
		printf("akita camera: uw: L2S_CTRL %#x (%u mV if 6-bit) L12S_CTRL %#x (%u mV)\n", l2, 300 + (l2 & 0x3f) * 25 / 2,
		    l12, 700 + (l12 & 0x3f) * 25);
		if (PE_parse_boot_argn("camera_l2s", &set, sizeof(set)) && set) {
			uint8_t v = (uint8_t)((l2 & 0xc0) | (set & 0x3f));

			spmic(true, S2MPG15_PM, 0x30, &v);
			delay(1000);
			spmic(false, S2MPG15_PM, 0x30, &l2);
			printf("akita camera: uw: L2S_CTRL now %#x\n", l2);
		}
	}
	if (!i2c_bus_up(c->bus)) {
		return;
	}
	for (on = 0; on < 4 && c->ldo[on] != 0; on++) {
		if (!slg_ldo_on(c->ldo[on], c->mv[on])) {
			goto down;
		}
	}
	delay(1000);
	pin_out(c->reset_bank, c->reset_pin, true);
	mclk(c->clk, c->clk_bank, c->clk_pin, true);
	delay(10000);
	if (!imx712_mode(c)) {
		goto down;
	}
	cam_smc(SMC_PRIV_REG, PMU_CSI_PHY_ISO, PRIV_REG_WRITE, rd(pmu + 0x1ebc) | 1u);
	for (unsigned i = 0; i < sizeof(uw_setup) / sizeof(uw_setup[0]); i++) {
		wr(csis + (uw_setup[i].pa - ISPFE_CSIS_PHYS), uw_setup[i].val);
	}
	wr(sysreg + 0x500, rd(sysreg + 0x500) | 3u);
	PE_parse_boot_argn("camera_uwfe", &uwfe, sizeof(uwfe));
	if (uwfe) {
		fe = ml_io_map(ISPFE_FE_PHYS, 0x100000);
		wr(fe + 0x20008, 0xf);          /* (the top, as the front's setup has it) */
		wr(fe + 0x20010, 1);
		wr(fe + 0x20094, 0x3fffffff);
		wr(fe + 0x2011c, 1);
		for (unsigned i = 0; i < sizeof(uw_fe_setup) / sizeof(uw_fe_setup[0]); i++) {
			wr(fe + (uw_fe_setup[i].pa - ISPFE_FE_PHYS), uw_fe_setup[i].val);
		}
		wr(fe + 0x200a0, 2);
		printf("akita camera: uw: block 1 set up (%u writes) and started\n", (unsigned)(sizeof(uw_fe_setup) / sizeof(uw_fe_setup[0])));
	}
	delay_for_interval(100, NSEC_PER_MSEC);
	printf("akita camera: uw: before the stream: D-PHY 0 clock +1e0: %x %x %x %x; lane 0 +c0: %x %x +e0: %x %x %x %x\n",
	    rd(csis + 0xc13e0 - 0x100), rd(csis + 0xc13e4 - 0x100), rd(csis + 0xc13e8 - 0x100), rd(csis + 0xc13ec - 0x100),
	    rd(csis + 0xc13c0), rd(csis + 0xc13c4), rd(csis + 0xc13e0), rd(csis + 0xc13e4), rd(csis + 0xc13e8), rd(csis + 0xc13ec));
	i2c_write16(c->bus, 0x1a, 0x0100, &one, 1);
	if (fe) {
		uint32_t lst[8] = { 0 };
		unsigned said = 0;

		for (unsigned ms = 0; ms < 300; ms++) {
			uint32_t v[8] = { rd(fe + 0x2008c), rd(fe + 0x20820), rd(fe + 0x20824), rd(fe + 0x20828), rd(fe + 0x20838),
				rd(fe + 0x208ac), rd(fe + 0x2089c), rd(fe + 0x20b08) };

			if ((ms == 0 || memcmp(v, lst, sizeof(v))) && said < 30) {
				printf("akita camera: uw: block 1 %3u ms: 2008c:%x 20820:%x 20824:%x 20828:%x 20838:%x 208ac:%x 2089c:%x 20b08:%x\n",
				    ms, v[0], v[1], v[2], v[3], v[4], v[5], v[6], v[7]);
				said++;
			}
			memcpy(lst, v, sizeof(v));
			if (v[2]) {
				wr(fe + 0x2008c, 2);
				wr(fe + 0x20824, v[2]);
				wr(fe + 0x20838, v[4]);
			}
			delay(1000);
		}
	} else {
		delay_for_interval(300, NSEC_PER_MSEC);
	}
	if (fe) {
		/* pdma-wrap (0x1c395000): the words Android reads each frame (always 0 there) */
		vm_offset_t pw = ml_io_map(0x1c395000ULL, 0x1000);

		printf("akita camera: uw: pdma-wrap +23c %#x +33c %#x +43c %#x +53c %#x\n", rd(pw + 0x23c), rd(pw + 0x33c), rd(pw + 0x43c),
		    rd(pw + 0x53c));
	}
	i2c_read16(c->bus, 0x1a, 0x0005, &fc, 1);
	{
		char line[400];
		int n = 0;

		for (uint32_t a = 0x1c101200; a < 0x1c101700; a += 4) {
			uint32_t v = rd(csis + (a - ISPFE_CSIS_PHYS));

			if ((a & 0xff) >= 0xb0 && v && v != 0xfa11fa11 && v != 0xdeadcafe) {
				n += snprintf(line + n, sizeof(line) - (size_t)n, " %x:%x", a, v);
			}
			if (n > 300) {
				printf("akita camera: uw: streaming: D-PHY 0:%s\n", line);
				n = 0;
			}
		}
		if (n) {
			printf("akita camera: uw: streaming: D-PHY 0:%s\n", line);
		}
	}
	printf("akita camera: uw: streaming (sensor frame counter %u): CSIS link 0 +04 %#x +500 %#x +504 %#x +14 %#x +1c %#x\n", fc,
	    rd(csis + 4), rd(csis + 0x500), rd(csis + 0x504), rd(csis + 0x14), rd(csis + 0x1c));
	i2c_write16(c->bus, 0x1a, 0x0100, &zero, 1);
	wr(sysreg + 0x500, rd(sysreg + 0x500) & ~3u);
down:
	mclk(c->clk, c->clk_bank, c->clk_pin, false);
	pin_out(c->reset_bank, c->reset_pin, false);
	while (on-- > 0) {
		slg_ldo_off(c->ldo[on]);
	}
	printf("akita camera: uw: powered down\n");
}

